-- LOCAL / CI ONLY. Minimal config + anchor rows a freshly restored schema needs before the PG
-- harnesses run (a restored schema has no data). Config rows are the QA service area set the local
-- Supabase DB already carries; the trip/driver are anchors the rematch harness borrows an in-area
-- pickup + region from (rmch_iso config). Idempotent (ON CONFLICT DO NOTHING). No prod data.
SET client_min_messages = warning;
SELECT set_config('request.jwt.claims', '{"role":"service_role"}', false);
SELECT set_config('request.jwt.claim.role', 'service_role', false);

