-- Anchor driver + trip (raw insert: triggers / FKs off, fixture only).
DO $seed$
DECLARE
  v_sa uuid := 'e8425eef-519b-46f8-82cd-677bb2320655';
  v_region uuid := '43b21a14-ea12-4ab6-96ee-cbabbf547de9';
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.drivers WHERE id = 'eeeeeeee-eeee-eeee-eeee-eeeeeeeeeed1') THEN
    SET LOCAL session_replication_role = replica;
    INSERT INTO public.drivers (id, first_name, last_name, phone, email, region_id, service_area_id)
    VALUES ('eeeeeeee-eeee-eeee-eeee-eeeeeeeeeed1', 'CI', 'ANCHOR', '+440000009001', 'ci-anchor@test.invalid', v_region, v_sa);
    SET LOCAL session_replication_role = origin;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.trips WHERE id = 'eeeeeeee-eeee-eeee-eeee-eeeeeeeeeee1') THEN
    SET LOCAL session_replication_role = replica;
    INSERT INTO public.trips (id, passenger_id, pickup_address, dropoff_address, pickup_latitude, pickup_longitude,
                              dropoff_latitude, dropoff_longitude, financial_model, status, payment_method, payment_type,
                              service_area_id, locked_base_fare_pence, final_customer_fare_pence, estimated_total_pence)
    VALUES ('eeeeeeee-eeee-eeee-eeee-eeeeeeeeeee1', gen_random_uuid(), 'CI anchor pickup', 'CI anchor dropoff',
            52.0347, -0.7736, 52.0380, -0.7700, 'PLATFORM_COLLECTED', 'cancelled', 'CARD', 'CARD', v_sa, 800, 800, 800);
    SET LOCAL session_replication_role = origin;
  END IF;
END
$seed$;
